import { EventListenerList } from '../../../../../compat/util/EventListenerList.js';
import { ViewControlListener } from './ViewControlListener.js';

/**
 * The add/remove/fire ViewControlListener methods that each original control
 * carried (generated by NetBeans), mixed into the control classes.
 */
export const ViewControlListenerSupport = {
    addViewControlListener(listener) {
        if (this.listenerList == null) {
            this.listenerList = new EventListenerList();
        }
        this.listenerList.add(ViewControlListener, listener);
    },

    removeViewControlListener(listener) {
        this.listenerList && this.listenerList.remove(ViewControlListener, listener);
    },

    fireViewControlListenerControlDeactivated(event) {
        for (const l of this.listenerList ? this.listenerList.getListeners(ViewControlListener) : []) {
            l.controlDeactivated(event);
        }
    },

    fireViewControlListenerControlActivated(event) {
        for (const l of this.listenerList ? this.listenerList.getListeners(ViewControlListener) : []) {
            l.controlActivated(event);
        }
    },

    fireViewControlListenerControlStateChanged(event) {
        for (const l of this.listenerList ? this.listenerList.getListeners(ViewControlListener) : []) {
            l.controlStateChanged(event);
        }
    },
};
